/** Render variables as the lines of a dotenv file. */
export function renderEnvFile(vars: Record<string, string>): string {
  // Validate variable names
  for (const name of Object.keys(vars)) {
    if (!/^[A-Z_][A-Z0-9_]*$/.test(name)) {
      throw new RangeError(`Invalid variable name: ${name}`);
    }
  }

  // Sort variables by name
  const sortedNames = Object.keys(vars).sort();

  // Render each line
  const lines: string[] = [];
  for (const name of sortedNames) {
    const value = vars[name];

    // Check if value needs quoting
    if (value === "") {
      lines.push(`${name}=`);
    } else if (/^[a-zA-Z0-9_@%+=:,./-]*$/.test(value)) {
      lines.push(`${name}=${value}`);
    } else {
      // Escape special characters in quoted values
      const escapedValue = value
        .replace(/\\/g, "\\\\")
        .replace(/"/g, "\\\"")
        .replace(/\$/g, "\\$")
        .replace(/\n/g, "\\n")
        .replace(/\r/g, "\\r");
      lines.push(`${name}="${escapedValue}"`);
    }
  }

  return lines.join("\n") + (lines.length > 0 ? "\n" : "");
}
